const {readFileSync} = require('node:fs');
const {runInNewContext} = require('node:vm');
const {strict:assert} = require('node:assert');
const {join} = require('node:path');
const nav = {identity_labels:{a1:'甲（a1）',a10:'乙<&"（a10）'}};
const format = runInNewContext(readFileSync(join(__dirname,'../static/identity.js'),'utf8')+'\nidentityText', {nav});
assert.equal(format('a1',{}),'甲（a1）');
assert.equal(format('a10',{}),'乙<&"（a10）');
assert.equal(format('a1 正文',{}),'a1 正文');
assert.equal(format('u1',{u1:'你'}),'你');
assert.equal(format('worker',{}),'worker');
nav.identity_labels.a1='改名（a1）';
assert.equal(format('a1',{}),'改名（a1）');
console.log('前端仅查服务端身份投影；原文和非负责人语义通过');
